<template><AppShell title="消息" tab="messages"><template #actions><view class="message-actions"><button class="ui-button icon-button" aria-label="搜索消息" @click="showSearch=!showSearch"><AppIcon class="app-icon" name="search" /></button><button class="ui-button icon-button" aria-label="全部已读" @click="clearUnread"><AppIcon class="app-icon" name="clean" /></button></view></template><view class="pad" style="background:#fff"><view v-if="showSearch" class="search" style="margin-bottom:12px"><AppIcon class="app-icon" name="search" :size="18" /><input v-model="keyword" @blur="keyword=$event.detail.value" placeholder="搜索联系人或消息" /></view><view class="notice"><AppIcon class="app-icon" name="bell" :size="18" /><text>交易消息，及时掌握</text></view></view><StateView :loading="loading" :error="error" :count="conversations.length+notifications.length" title="还没有新消息" description="在道具详情中联系卖家，开始第一段对话" @retry="load" /><view v-if="!error&&!loading" class="message-list"><view class="message-row" @click="showNotifications=!showNotifications"><view class="message-system"><AppIcon class="app-icon" name="clipboard" :size="28" /></view><view class="flex-1"><view class="row between"><text class="message-name">订单与平台通知</text><text class="muted tiny">{{date(notifications[0]?.createdAt)}}</text></view><text class="message-preview">{{notifications[0]?.content||'暂无交易通知'}}</text></view><text v-if="unread" class="badge">{{unread}}</text></view><view v-if="showNotifications" class="notification-list"><view v-for="n in notifications" :key="n.id" class="notification-item" @click="openNotice(n)"><view class="row between"><text class="bold">{{n.isRead?'':'● '}}{{n.title}}</text><text class="muted tiny">{{date(n.createdAt)}}</text></view><text class="muted">{{n.content}}</text></view><button v-if="noticeMore" class="ui-button load-more" :disabled="moreBusy" @click="more(true)">更多通知</button></view><view v-for="c in conversations" :key="c.id" class="message-row" @click="go('chat/index',{id:c.id})"><GameArt avatar :size="52" :type="c.avatar" :src="c.avatar?.startsWith('/')?c.avatar:''" /><view class="flex-1"><view class="row between"><text class="message-name">{{c.nickname}}</text><text class="muted tiny">{{date(c.updatedAt)}}</text></view><text class="message-preview">{{c.lastMessage?.startsWith('/boost-media/')?'[图片]':c.lastMessage||'点击开始沟通道具交易'}}</text></view><text v-if="c.unread" class="badge">{{c.unread}}</text></view><view class="message-row" @click="go('account/index',{type:'help'})"><view class="message-system blue"><AppIcon class="app-icon" name="headset" :size="28" /></view><view><text class="message-name">帮助与客服</text><text class="message-preview">订单有问题，平台来协助</text></view><AppIcon class="app-icon" name="chevron" :size="16" /></view><text v-if="keyword&&!conversations.length" class="muted" style="display:block;text-align:center;padding:20px">未找到相关会话</text><button v-if="chatMore" class="ui-button load-more" :disabled="moreBusy" @click="more(false)">更多会话</button></view></AppShell></template>
<script setup>
import {ref,watch} from 'vue';import {onShow,onHide,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import StateView from '../../components/StateView.vue';import {request,requireLogin,go,date,safely,loadMe,toast} from '../../lib/api';const loading=ref(false),error=ref(''),conversations=ref([]),notifications=ref([]),showSearch=ref(false),showNotifications=ref(false),keyword=ref('');const unread=ref(0),chatPage=ref(1),noticePage=ref(1),chatMore=ref(false),noticeMore=ref(false),moreBusy=ref(false);let epoch=0,searchTimer;watch(keyword,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(load,350)});onHide(()=>{clearTimeout(searchTimer);epoch++});onUnload(()=>{clearTimeout(searchTimer);epoch++});onShow(()=>{if(requireLogin())load()});async function load(){const current=++epoch;loading.value=true;error.value='';try{const r=await Promise.all([request('/boost/conversations','GET',{keyword:keyword.value}),request('/boost/notifications')]);if(current!==epoch)return;conversations.value=r[0].items;chatMore.value=r[0].hasMore;notifications.value=r[1].items;noticeMore.value=r[1].hasMore;unread.value=r[1].unread;chatPage.value=1;noticePage.value=1;await loadMe()}catch(e){if(current===epoch)error.value=e.message}finally{if(current===epoch)loading.value=false}}async function clearUnread(){await safely(()=>request('/boost/notifications/read-all','POST'),'已标记为全部已读');load()}
async function more(notice){if(moreBusy.value)return;moreBusy.value=true;const current=epoch;try{const page=notice?noticePage:chatPage,rows=notice?notifications:conversations,d=await request(notice?'/boost/notifications':'/boost/conversations','GET',{page:page.value+1,keyword:notice?'':keyword.value});if(current!==epoch)return;rows.value=[...new Map([...rows.value,...d.items].map(x=>[x.id,x])).values()];page.value++;(notice?noticeMore:chatMore).value=d.hasMore}catch(e){toast(e.message)}finally{moreBusy.value=false}}
async function openNotice(n){if(!n.isRead){try{await request(`/boost/notifications/${n.id}/read`,'POST');n.isRead=true;unread.value=Math.max(0,unread.value-1)}catch(e){toast(e.message);return}}if(n.orderId){go('orders/detail',{id:n.orderId});return}if(n.title.includes('提现')){go('wallet/index');return}if(n.title.includes('实名认证')){go('identity/index');return}if(n.title.includes('认证')){go('certification/index');return}uni.showModal({title:n.title,content:n.content,showCancel:false,confirmText:'我知道了'})}
</script>
<style scoped>.message-actions{display:flex;flex-direction:row;align-items:center;gap:8px}.message-actions .icon-button{width:44px;height:44px;border-radius:50%;background:#f6f6f8}.message-actions .icon-button:active{background:#fff5a8}.message-list{background:#fff;min-height:60vh;padding:0 16px}.message-row{display:flex;align-items:center;gap:12px;min-height:92px;border-bottom:1px solid #f2f2f4;cursor:pointer}.message-row .game-art,.message-system{width:52px;height:52px;border-radius:50%}.message-system{display:flex;align-items:center;justify-content:center;background:#ffe433;flex-shrink:0}.blue{background:#d4e9ff}.message-name{font-size:16px;font-weight:700;display:block}.message-preview{display:-webkit-box;-webkit-line-clamp:1;-webkit-box-orient:vertical;overflow:hidden;color:#95959e;font-size:13px;margin-top:7px}.notification-list{padding:0 8px 0 22px}.notification-item{padding:14px 0;border-bottom:1px solid #eee;display:flex;flex-direction:column;gap:5px;font-size:12px}.message-row>.app-icon:last-child{margin-left:auto}</style>
